"""
Generate a .env with strong random keys (does nothing if .env already exists).

    python init_env.py

IMPORTANT: back up .env. VAULT_KEY encrypts every stored password; if you lose
or change it, existing passwords can no longer be decrypted.
"""
import secrets
from pathlib import Path

from cryptography.fernet import Fernet

path = Path(__file__).resolve().parent / ".env"
if path.exists():
    raise SystemExit(".env already exists - leaving it untouched.")

path.write_text(
    "# Generated by init_env.py. Keep this file private and back it up.\n"
    f"SECRET_KEY={secrets.token_hex(32)}\n"
    f"VAULT_KEY={Fernet.generate_key().decode()}\n"
    "\n# Set to 1 when running behind nginx/Caddy/Traefik (correct https links + client IPs)\n"
    "# BEHIND_PROXY=1\n"
    "\n# Public URL of this install (used for links in expiry-alert emails)\n"
    "# APP_BASE_URL=https://vault.example.com\n"
    "\n# Encrypts backups made by `python backup.py create` (cron). Keep it safe: backups can't be restored without it.\n"
    "# BACKUP_PASSPHRASE=\n"
    "# BACKUP_KEEP=14\n"
    "\n# Max total size of attachments embedded in a playbook PDF (MB)\n"
    "# PLAYBOOK_MAX_ATTACH_MB=100\n"
)
try:
    path.chmod(0o600)
except Exception:
    pass
print(f"Wrote {path}. Back it up somewhere safe.")
